START TRANSACTION;
CREATE TABLE IF NOT EXISTS `ext_quotemaker_templates` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`name` VARCHAR(255) NOT NULL,`vertical` VARCHAR(255) NULL,`service_type` VARCHAR(255) NULL,`variation` VARCHAR(255) NULL,`theme` VARCHAR(255) NULL,`visual_mode` VARCHAR(255) NULL,`package_tier` VARCHAR(255) NULL,`summary` TEXT NULL,`pricing_model` VARCHAR(255) NULL,`metadata_json` LONGTEXT NULL,`is_active` TINYINT(1) NOT NULL DEFAULT 1,`created_at` TIMESTAMP NULL,`updated_at` TIMESTAMP NULL,PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `ext_quotemaker_quote_bots` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`template_id` BIGINT UNSIGNED NULL,`name` VARCHAR(255) NOT NULL,`follow_up_delay_hours` INT NOT NULL DEFAULT 24,`follow_up_channel` VARCHAR(255) NOT NULL DEFAULT 'email_sms',`auto_create_booking` TINYINT(1) NOT NULL DEFAULT 0,`auto_create_job` TINYINT(1) NOT NULL DEFAULT 0,`auto_negotiate` TINYINT(1) NOT NULL DEFAULT 0,`negotiation_rules_json` LONGTEXT NULL,`status` VARCHAR(50) NOT NULL DEFAULT 'draft',`created_at` TIMESTAMP NULL,`updated_at` TIMESTAMP NULL,PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
COMMIT;